// R1 #1419 independent oracle for R1-STR-OPS-COUNT-INDEX-003
using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
public static class R1Oracle
{
    public const string Claim = "forall";
    public const bool Exhaustive = false;
    public const bool Checked = true;
    public static bool Hyp(string? s) => true;
    public static int Body(string? s)
    {
        return s!.Substring(1, 1).Length;
    }
    public static bool Prop(string? s, int result) => result == 4;
    public static bool HypO(object?[] a) => Hyp((string?)a[0]);
    public static bool HasBody => true;
    public static object? BodyO(object?[] a) => Body((string?)a[0]);
    public static bool PropO(object?[] a, object? r) => Prop((string?)a[0], (int)r!);
    public static IEnumerable<object?[]> Inputs()
    {
        yield return new object?[] { (string?)(null) };
        yield return new object?[] { (string?)("") };
        yield return new object?[] { (string?)("a") };
        yield return new object?[] { (string?)("abc") };
        yield return new object?[] { (string?)("ABC") };
        yield return new object?[] { (string?)("b") };
        yield return new object?[] { (string?)("\u00e9") };
        yield return new object?[] { (string?)("\ud83d\ude00ab") };
        yield return new object?[] { (string?)("\u200dabc") };
        yield return new object?[] { (string?)("aaaa") };
        yield return new object?[] { (string?)("zzz") };
        yield return new object?[] { (string?)("a\u0000b") };
    }
}

public static class Repro
{
    public static int Main()
    {
        int reached = 0;
        foreach (var a in R1Oracle.Inputs())
        {
            bool hyp; object? r = null; bool ok; string why;
            try { hyp = R1Oracle.HypO(a); } catch { continue; }
            if (!hyp) continue;
            if (R1Oracle.HasBody) { try { r = R1Oracle.BodyO(a); } catch { continue; } }
            reached++;
            try { ok = R1Oracle.PropO(a, r); why = "false"; } catch (Exception e) { ok = false; why = "throws " + e.GetType().Name; }
            var shown = "(" + string.Join(", ", a.Select(v => v is null ? "null" : v is Array arr ? "[" + string.Join(", ", arr.Cast<object>()) + "]" : v is string s ? "\"" + s + "\"" : Convert.ToString(v, System.Globalization.CultureInfo.InvariantCulture))) + ")";
            if (R1Oracle.Claim == "exists") { if (ok) { Console.WriteLine("witness " + shown); return 0; } continue; }
            if (!ok) { Console.WriteLine("property " + why + " at " + shown + (R1Oracle.HasBody ? " result=" + Convert.ToString(r, System.Globalization.CultureInfo.InvariantCulture) : "")); return 1; }
        }
        Console.WriteLine((R1Oracle.Claim == "exists" ? "no witness" : "no violation") + " in the registered domain; reached inputs: " + reached);
        return 0;
    }
}
